contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test entry
    function run(bytes32 identifier, uint256 time, bytes calldata ancillaryData, bytes32 assertionId, bool assertedTruthfully) public payable {
        // the rule we test: calls protected by onlyOptimisticAsserter should revert when msg.sender != optimisticAsserter
        // We will call requestPrice, assertionResolvedCallback, assertionDisputedCallback from this contract

        // Ensure this contract has some ether if caller supplied value for safety (not required by C but allowed)
        if (msg.value > 0) {
            // no-op: funds are held by this contract; nothing required
        }

        bool reverted_requestPrice;
        bool reverted_resolvedCallback;
        bool reverted_disputedCallback;

        // Each state-changing call must be a top-level statement.
        // Try requestPrice
        try c.requestPrice(identifier, time, ancillaryData) {
            reverted_requestPrice = false;
        } catch {
            reverted_requestPrice = true;
        }

        // Try assertionResolvedCallback
        try c.assertionResolvedCallback(assertionId, assertedTruthfully) {
            reverted_resolvedCallback = false;
        } catch {
            reverted_resolvedCallback = true;
        }

        // Try assertionDisputedCallback
        try c.assertionDisputedCallback(assertionId) {
            reverted_disputedCallback = false;
        } catch {
            reverted_disputedCallback = true;
        }

        // Read optimisticAsserter address to determine whether this contract is equal to it
        // and thus whether the calls should have been allowed. The intended rule: if this contract
        // is NOT the optimisticAsserter, then all three calls must revert; otherwise they may succeed.
        address opt = address(c.optimisticAsserter());
        bool isOptimisticAsserter = (opt == address(this));

        // General rule assertion: when caller != optimisticAsserter then all three protected calls reverted.
        assert(isOptimisticAsserter || (reverted_requestPrice && reverted_resolvedCallback && reverted_disputedCallback));
    }

    // allow receiving ETH if needed
    receive() external payable {}
}

