contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public entry that checks that non-optimisticAsserter callers cannot call onlyOptimisticAsserter-protected functions
    // Parameters: caller address to pretend (we cannot change msg.sender externally), so instead we drive behavior by attempting calls
    // from this contract (which is the deployer of c) — optimisticAsserter is set at c construction; we can compare address(optimisticAsserter)
    function run() public payable {
        // Read the optimistic asserter address from c
        address optimisticAddr = address(c.optimisticAsserter());

        // We'll call the three onlyOptimisticAsserter functions from this contract (msg.sender == address(this)).
        // They should revert unless this contract is the optimisticAsserter. We detect revert using try/catch.

        bool reqPriceReverted;
        bool resolvedReverted;
        bool disputedReverted;

        // Prepare some dummy args
        bytes32 id = keccak256(abi.encodePacked("id", block.timestamp));
        uint256 t = block.timestamp;
        bytes memory ancillary = abi.encodePacked("anc");
        bytes32 assertionId = keccak256(abi.encodePacked("ass", block.timestamp));

        // Call requestPrice (non-view, protected)
        try c.requestPrice(id, t, ancillary) {
            reqPriceReverted = false;
        } catch {
            reqPriceReverted = true;
        }

        // Call assertionResolvedCallback (non-view, protected)
        try c.assertionResolvedCallback(assertionId, true) {
            resolvedReverted = false;
        } catch {
            resolvedReverted = true;
        }

        // Call assertionDisputedCallback (non-view, protected)
        try c.assertionDisputedCallback(assertionId) {
            disputedReverted = false;
        } catch {
            disputedReverted = true;
        }

        // General rule: if this contract is NOT the optimisticAsserter, then all three calls must have reverted;
        // if this contract IS the optimisticAsserter, then none of them should have reverted.
        bool amOptimistic = (optimisticAddr == address(this));

        assert( (amOptimistic && !reqPriceReverted && !resolvedReverted && !disputedReverted) ||
                (!amOptimistic && reqPriceReverted && resolvedReverted && disputedReverted) );
    }

    // receive in case c or other interactions send Ether
    receive() external payable {}
}

