contract InvMutTest {
    C c;
    // deploy with existing C instance
    constructor(C _c) { c = _c; }

    // single public function taking inputs used to call requestPrice
    function run(address optimisticAsserterAddr, bytes32 identifier, uint256 time, bytes calldata ancillaryData) public payable {
        require(optimisticAsserterAddr != address(0));
        // Precondition: the c was constructed with some optimisticAsserter; ensure we call only if provided addr equals c.optimisticAsserter()
        // We will only attempt the state-changing call if optimisticAsserterAddr equals the recorded optimisticAsserter in c.
        // Read the public immutable optimisticAsserter from c
        address recorded = address(c.optimisticAsserter());

        bool callSucceeded = false;
        if (optimisticAsserterAddr == recorded) {
            // We need to call requestPrice as if msg.sender == optimisticAsserter; since the checker deploys c and then calls run,
            // msg.sender for calls from this contract is this contract address. To simulate being the optimisticAsserter, the test
            // requires that recorded == address(this) beforehand would be used, but we cannot change c. Instead we check the case
            // where the recorded optimisticAsserter equals address(this) and only then perform the call, which must succeed.
            if (recorded == address(this)) {
                // Call should succeed and not revert. We capture revert using try/catch on external call.
                try c.requestPrice(identifier, time, ancillaryData) {
                    callSucceeded = true;
                } catch {
                    callSucceeded = false;
                }
            }
        }

        // General rule: if this contract is the optimisticAsserter for c (recorded == address(this)), then calling requestPrice must not revert
        // and the optimisticAsserter getter remains unchanged (still recorded). This asserts a relation between parameters and observable state.
        assert((recorded != address(this)) || (callSucceeded && address(c.optimisticAsserter()) == recorded));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function taking inputs used to call requestPrice
    function run(bytes32 identifier, uint256 time, bytes calldata ancillaryData) public payable {
        // read the public immutable optimisticAsserter
        address recorded = address(c.optimisticAsserter());

        // We'll attempt the state-changing call only if this contract is the recorded optimisticAsserter.
        // The call must be a top-level statement. Use try/catch to observe revert without nesting the call inside other control flow.
        bool callReverted;
        if (recorded == address(this)) {
            try c.requestPrice(identifier, time, ancillaryData) {
                callReverted = false;
            } catch {
                callReverted = true;
            }
        } else {
            // If not the optimistic asserter, we don't call; mark as not-reverted for the implication to hold vacuously
            callReverted = false;
        }

        // General rule: if this contract is the optimisticAsserter, then requestPrice must not revert
        // and optimisticAsserter() must still equal the previously recorded address.
        assert((recorded != address(this)) || (!callReverted && address(c.optimisticAsserter()) == recorded));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public function performing the property check
    function run(bytes32 identifier, uint256 time, bytes calldata ancillaryData) public payable {
        // Read immutable optimisticAsserter before any state-changing call
        address recorded = address(c.optimisticAsserter());

        // We will attempt the state-changing call as a top-level statement only when this contract
        // is the recorded optimistic asserter. To satisfy the requirement that the call be a
        // top-level statement, we perform two separate branches where the call itself is
        // top-level in one branch and absent in the other. We record whether it reverted.
        bool callReverted = false;

        if (recorded == address(this)) {
            // Top-level state-changing call (may revert). Use try/catch at top level as allowed.
            try c.requestPrice(identifier, time, ancillaryData) {
                callReverted = false;
            } catch {
                callReverted = true;
            }
        } else {
            // Do not call when not the optimistic asserter; mark as not-reverted for vacuous implication
            callReverted = false;
        }

        // General rule: if this contract was the recorded optimistic asserter and the call succeeded
        // (did not revert), then optimisticAsserter() must still equal the previously recorded address.
        assert((recorded != address(this)) || (callReverted || address(c.optimisticAsserter()) == recorded));
    }

    receive() external payable {}
}

