contract InvMutTest {
    C c;
    address payable optimisticAsserterCandidate;

    constructor(C _c) {
        c = _c;
        optimisticAsserterCandidate = payable(address(this));
    }

    // single public function with inputs to drive calls
    function run(address callerForNonAllowed, bytes32 identifier, uint256 time, bytes calldata ancillaryData) public payable {
        require(callerForNonAllowed != address(0));
        // We know c.optimisticAsserter() is public, query it
        address asserterAddr = address(c.optimisticAsserter());

        // CASE A: call requestPrice from the optimisticAsserter (msg.sender must equal optimisticAsserter)
        // We cannot make external calls with arbitrary msg.sender in a single transaction, but the contract InvMutTest is the deployer and runs as msg.sender when calling c.
        // So there are two possibilities: either optimisticAsserter == address(this) in which case the call should NOT revert, or it is different and the call SHOULD revert because of onlyOptimisticAsserter.

        bool callFromThisReverted;
        try c.requestPrice(identifier, time, ancillaryData) {
            callFromThisReverted = false;
        } catch {
            callFromThisReverted = true;
        }

        // CASE B: simulate a call from a different caller by invoking the same call but via a low-level call through address(c).
        // We cannot change msg.sender for external calls; however we can check behavior when optimisticAsserter equals some other address:
        // If optimisticAsserter == address(this) then calls from a different caller should revert; else, calls from this should revert.

        // Attempt to invoke the callbacks as well and record revert behavior
        bool resolvedCallbackReverted;
        try c.assertionResolvedCallback(bytes32(0), true) {
            resolvedCallbackReverted = false;
        } catch {
            resolvedCallbackReverted = true;
        }

        bool disputedCallbackReverted;
        try c.assertionDisputedCallback(bytes32(0)) {
            disputedCallbackReverted = false;
        } catch {
            disputedCallbackReverted = true;
        }

        // The general rule: exactly when the optimisticAsserter getter equals address(this), the three calls should NOT revert; otherwise all three should revert.
        bool expectedNoRevert = (asserterAddr == address(this));

        assert((!expectedNoRevert && callFromThisReverted && resolvedCallbackReverted && disputedCallbackReverted) || (expectedNoRevert && !callFromThisReverted && !resolvedCallbackReverted && !disputedCallbackReverted));
    }

    receive() external payable {}
}

