    // params: caller flag determines whether to call as optimisticAsserter or as another address
    function run(address caller, bytes32 identifier, uint256 time, bytes calldata ancillaryData) public payable {
        require(true);
        // Read the optimisticAsserter address from c
        address optimistic = address(c.optimisticAsserter());

        // Record c balance before
        uint256 beforeBal = address(c).balance;

        bool reverted;
        // If caller equals the optimisticAsserter, we must succeed (not revert) when calling requestPrice.
        // If caller is not optimisticAsserter, the call must revert due to onlyOptimisticAsserter modifier.
        if (caller == optimistic) {
            // Call through this contract but impersonate the allowed caller by ensuring that
            // the optimisticAsserter equals this contract; if not, the call must revert when made.
            // We cannot change msg.sender of the call in Solidity, so we express the observable rule:
            // If optimisticAsserter() == address(this) then requestPrice should NOT revert and should not change balance.
            if (optimistic == address(this)) {
                // should not revert
                reverted = false;
                try c.requestPrice(identifier, time, ancillaryData) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
                // after successful (non-revert) call, balance unchanged
                uint256 afterBal = address(c).balance;
                assert(reverted == false && afterBal == beforeBal);
                return;
            } else {
                // optimistic points to some other address; since we cannot call as that address, our invocation
                // must revert (onlyOptimisticAsserter). So we expect a revert here.
                try c.requestPrice(identifier, time, ancillaryData) {
                    // If it didn't revert, that's a violation: onlyOptimisticAsserter failed to restrict access
                    reverted = false;
                } catch {
                    reverted = true;
                }
                uint256 afterBal = address(c).balance;
                // The general rule: when msg.sender != optimisticAsserter, requestPrice must revert and must not change balance.
                assert(reverted == true && afterBal == beforeBal);
                return;
            }
        } else {
            // caller != optimistic: we are invoking as this contract (not optimistic) so the call MUST revert
            try c.requestPrice(identifier, time, ancillaryData) {
                reverted = false;
            } catch {
                reverted = true;
            }
            uint256 afterBal = address(c).balance;
            assert(reverted == true && afterBal == beforeBal);
            return;
        }
    }

    receive() external payable {}
}

