    address testerCaller;

    constructor(C _c) { c = _c; }

    // single public entry exercising the access control modifier onlyOptimisticAsserter
    // params: addresses to act as callers and a bytes payload and identifier/time
    function run(address caller1, address caller2, bytes calldata ancillaryData, bytes32 identifier, uint256 time) public payable {
        require(caller1 != caller2, "need two distinct callers");
        // record optimisticAsserter address via public getter
        address optimistic = address(c.optimisticAsserter());

        // We will attempt three calls (requestPrice, assertionResolvedCallback, assertionDisputedCallback)
        // once from optimisticAsserter (should not revert) and once from a different caller (should revert due to modifier)

        // helper: low-level call to c.requestPrice as optimistic
        bool ok_opt_request;
        bytes memory data_request = abi.encodeWithSelector(c.requestPrice.selector, identifier, time, ancillaryData);
        (ok_opt_request, ) = optimistic.call{value: 0}(data_request);

        // low-level call to requestPrice from caller1
        bool ok_other_request;
        (ok_other_request, ) = caller1.call(data_request);

        // assertionResolvedCallback: encode with some random assertionId and truth value
        bytes32 assertionId = keccak256(abi.encodePacked(identifier, time, ancillaryData));
        bytes memory data_resolved = abi.encodeWithSelector(c.assertionResolvedCallback.selector, assertionId, true);

        bool ok_opt_resolved;
        (ok_opt_resolved, ) = optimistic.call(data_resolved);

        bool ok_other_resolved;
        (ok_other_resolved, ) = caller2.call(data_resolved);

        // assertionDisputedCallback
        bytes memory data_disputed = abi.encodeWithSelector(c.assertionDisputedCallback.selector, assertionId);

        bool ok_opt_disputed;
        (ok_opt_disputed, ) = optimistic.call(data_disputed);

        bool ok_other_disputed;
        (ok_other_disputed, ) = caller1.call(data_disputed);

        // General rule: calls made by the optimisticAsserter must succeed (not revert), while calls made by other addresses must not succeed (must revert).
        // Expressed as: optimistic calls succeeded for all three, and at least one of the non-optimistic calls failed for each of the three.
        assert(
            ok_opt_request && ok_opt_resolved && ok_opt_disputed
            && (!ok_other_request) && (!ok_other_resolved) && (!ok_other_disputed)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry exercising access control: we perform the three calls
    // from two different senders by using try/catch on c.* calls. The optimisticAsserter
    // calls must not revert; calls from some other address must revert.
    function run(address other, bytes calldata ancillaryData, bytes32 identifier, uint256 time) public payable {
        require(other != address(0), "other must be non-zero");

        // determine optimistic asserter address via public getter
        address optimistic = address(c.optimisticAsserter());

        // Prepare a synthetic assertionId for callbacks
        bytes32 assertionId = keccak256(abi.encodePacked(identifier, time, ancillaryData));

        // Attempt call.requestPrice from optimisticAsserter by calling c.requestPrice directly
        // but we must make the call originate from optimisticAsserter. Since the checker runs this
        // single transaction with msg.sender == address(this) for calls on c, we cannot change msg.sender.
        // However the contract C's onlyOptimisticAsserter modifier checks msg.sender == optimisticAsserter.
        // To observe behavior from both optimistic and non-optimistic callers, we rely on the fact
        // that c.requestPrice is external and will revert when msg.sender != optimistic. We therefore
        // check the two cases by reading optimistic and comparing with address(this):

        bool optIsThis = (optimistic == address(this));

        // Call requestPrice: if this contract is the optimistic asserter, it should NOT revert.
        bool req_reverted;
        try c.requestPrice(identifier, time, ancillaryData) {
            req_reverted = false;
        } catch {
            req_reverted = true;
        }

        // Call assertionResolvedCallback
        bool res_reverted;
        try c.assertionResolvedCallback(assertionId, true) {
            res_reverted = false;
        } catch {
            res_reverted = true;
        }

        // Call assertionDisputedCallback
        bool dis_reverted;
        try c.assertionDisputedCallback(assertionId) {
            dis_reverted = false;
        } catch {
            dis_reverted = true;
        }

        // General rule expressed as one assert:
        // If this contract is the optimisticAsserter (optimistic == address(this)), NONE of the three calls reverted.
        // If this contract is NOT the optimisticAsserter, ALL three calls reverted.
        // This captures that only the optimisticAsserter can call those functions without reverting.
        assert((optIsThis && (!req_reverted) && (!res_reverted) && (!dis_reverted)) ||
               (!optIsThis && req_reverted && res_reverted && dis_reverted));
    }

    receive() external payable {}
}

