contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // try callers other than the optimistic asserter to ensure onlyOptimisticAsserter modifier blocks them
    // We take arbitrary inputs for the price request and assertion id.
    function run(bytes32 identifier, uint256 time, bytes calldata ancillaryData, bytes32 assertionId, bool assertedTruthfully) public payable {
        require(true);

        // Prepare call data for requestPrice and callbacks
        // Call as this contract (which is NOT the optimisticAsserter) and catch whether it reverts
        bool reqReverted;
        try c.requestPrice(identifier, time, ancillaryData) {
            reqReverted = false;
        } catch {
            reqReverted = true;
        }

        bool resolvedReverted;
        try c.assertionResolvedCallback(assertionId, assertedTruthfully) {
            resolvedReverted = false;
        } catch {
            resolvedReverted = true;
        }

        bool disputedReverted;
        try c.assertionDisputedCallback(assertionId) {
            disputedReverted = false;
        } catch {
            disputedReverted = true;
        }

        // The general rule: when called by any address other than the optimisticAsserter (here: this contract),
        // all three functions must revert due to onlyOptimisticAsserter modifier. Since the optimisticAsserter
        // address is set at c construction and is not this contract (the checker deploys a fresh c and passes it
        // into this test), at least one of the calls SHOULD revert. However to state a general provable rule we
        // assert that either all three revert or at least the requestPrice reverts. This ensures we observe the
        // access control enforced by onlyOptimisticAsserter.
        // More strictly: require that requestPrice reverts and the two callbacks revert as well. We assert that
        // requestPrice reverts AND the callbacks revert. This encodes the intended access restriction.

        assert(reqReverted && resolvedReverted && disputedReverted);
    }

    receive() external payable {}
}

