    // single public entry driving the property-based test
    // params: callerIsOptimisticAsserter controls whether we simulate calls as the optimistic asserter
    // We cannot change msg.sender for calls from this contract, but we can observe optimisticAsserter() value
    function run(bool callRequestPrice, bytes32 identifier, uint256 time, bytes calldata ancillaryData, bytes32 assertionId, bool assertedTruthfully, bool callCallbacks) public payable {
        require(true);

        // read optimisticAsserter address
        address opt = address(c.optimisticAsserter());

        // We will attempt calls from this contract (msg.sender == address(this)). According to C, only optimisticAsserter may call
        bool isCallerOptimisticAsserter = (opt == address(this));

        // Attempt requestPrice and capture whether it reverted
        bool requestPriceReverted;
        try c.requestPrice(identifier, time, ancillaryData) {
            requestPriceReverted = false;
        } catch {
            requestPriceReverted = true;
        }

        // Attempt assertionResolvedCallback and capture revert
        bool resolvedCallbackReverted;
        try c.assertionResolvedCallback(assertionId, assertedTruthfully) {
            resolvedCallbackReverted = false;
        } catch {
            resolvedCallbackReverted = true;
        }

        // Attempt assertionDisputedCallback and capture revert
        bool disputedCallbackReverted;
        try c.assertionDisputedCallback(assertionId) {
            disputedCallbackReverted = false;
        } catch {
            disputedCallbackReverted = true;
        }

        // If this contract is the optimistic asserter, none of the three calls should revert.
        // If it is not the optimistic asserter, all three should revert because modifier onlyOptimisticAsserter enforces msg.sender == optimisticAsserter
        assert(
            (isCallerOptimisticAsserter && !requestPriceReverted && !resolvedCallbackReverted && !disputedCallbackReverted) ||
            (!isCallerOptimisticAsserter && requestPriceReverted && resolvedCallbackReverted && disputedCallbackReverted)
        );
    }

