    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing the property checks
    // We take inputs that are forwarded to the calls; msg.sender for calls from this contract is address(this).
    function run(bool doRequestPrice, bytes32 identifier, uint256 time, bytes calldata ancillaryData, bytes32 assertionId, bool assertedTruthfully, bool doCallbacks) public payable {
        require(true);

        // Read the optimisticAsserter address from c
        address opt = address(c.optimisticAsserter());

        // Determine whether this test contract is the optimistic asserter
        bool isCallerOptimisticAsserter = (opt == address(this));

        // Attempt requestPrice (only called if doRequestPrice to keep single execution path flexible)
        bool requestPriceReverted = false;
        if (doRequestPrice) {
            try c.requestPrice(identifier, time, ancillaryData) {
                requestPriceReverted = false;
            } catch {
                requestPriceReverted = true;
            }
        }

        // Attempt assertionResolvedCallback and assertionDisputedCallback if requested
        bool resolvedCallbackReverted = false;
        bool disputedCallbackReverted = false;
        if (doCallbacks) {
            try c.assertionResolvedCallback(assertionId, assertedTruthfully) {
                resolvedCallbackReverted = false;
            } catch {
                resolvedCallbackReverted = true;
            }

            try c.assertionDisputedCallback(assertionId) {
                disputedCallbackReverted = false;
            } catch {
                disputedCallbackReverted = true;
            }
        }

        // General rule: if this contract is the optimisticAsserter, none of the invoked calls revert;
        // otherwise, all invoked calls revert. We only assert over the calls that were actually invoked.
        assert(
            (isCallerOptimisticAsserter && (
                (!doRequestPrice || !requestPriceReverted) &&
                (!doCallbacks || !resolvedCallbackReverted) &&
                (!doCallbacks || !disputedCallbackReverted)
            )) ||
            (!isCallerOptimisticAsserter && (
                (!doRequestPrice || requestPriceReverted) &&
                (!doCallbacks || resolvedCallbackReverted) &&
                (!doCallbacks || disputedCallbackReverted)
            ))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing the property checks
    // Inputs choose which of the three functions to invoke and their parameters.
    function run(bool callRequestPrice, bytes32 identifier, uint256 time, bytes calldata ancillaryData, bool callResolved, bytes32 assertionIdRes, bool assertedTruthfully, bool callDisputed, bytes32 assertionIdDis) public payable {
        require(true);

        // Read optimisticAsserter address (view call allowed inside function)
        address opt = address(c.optimisticAsserter());
        bool isOpt = (opt == address(this));

        // Perform each call as a TOP-LEVEL statement and capture whether they revert using try/catch.
        bool reqReverted;
        if (callRequestPrice) {
            try c.requestPrice(identifier, time, ancillaryData) {
                reqReverted = false;
            } catch {
                reqReverted = true;
            }
        } else {
            reqReverted = false; // not invoked, treat as non-reverted for the assertion logic
        }

        bool resReverted;
        if (callResolved) {
            try c.assertionResolvedCallback(assertionIdRes, assertedTruthfully) {
                resReverted = false;
            } catch {
                resReverted = true;
            }
        } else {
            resReverted = false;
        }

        bool disReverted;
        if (callDisputed) {
            try c.assertionDisputedCallback(assertionIdDis) {
                disReverted = false;
            } catch {
                disReverted = true;
            }
        } else {
            disReverted = false;
        }

        // General rule: for each invoked call, it must revert exactly when this contract is NOT the optimisticAsserter.
        assert(
            (
                (!callRequestPrice || (reqReverted == (!isOpt))) &&
                (!callResolved || (resReverted == (!isOpt))) &&
                (!callDisputed || (disReverted == (!isOpt)))
            )
        );
    }

    receive() external payable {}
}

