    // Single public function: all state-changing calls on c are top-level statements (try/catch per call).
    function run(bool doRequestPrice, bytes32 identifier, uint256 time, bytes calldata ancillaryData, bool doResolved, bytes32 assertionIdRes, bool assertedTruthfully, bool doDisputed, bytes32 assertionIdDis) public payable {
        require(true);

        // Observe optimisticAsserter via public getter
        address opt = address(c.optimisticAsserter());

        // For each possible call we perform a top-level try/catch (state-changing call must be top-level).
        bool reqReverted;
        if (doRequestPrice) {
            try c.requestPrice(identifier, time, ancillaryData) {
                reqReverted = false;
            } catch {
                reqReverted = true;
            }
        } else {
            // Not invoked: treat as not-reverted for the universal rule (since rule concerns invoked calls)
            reqReverted = false;
        }

        bool resReverted;
        if (doResolved) {
            try c.assertionResolvedCallback(assertionIdRes, assertedTruthfully) {
                resReverted = false;
            } catch {
                resReverted = true;
            }
        } else {
            resReverted = false;
        }

        bool disReverted;
        if (doDisputed) {
