                disReverted = false;
            } catch {
                disReverted = true;
            }
        } else {
            disReverted = false;
        }

        // General rule: for each invoked call, it reverts iff this contract is NOT the optimisticAsserter
        bool ruleReq = (!doRequestPrice) || (reqReverted == (address(this) != opt));
        bool ruleRes = (!doResolved) || (resReverted == (address(this) != opt));
