contract InvMutTest {
    C c;
    address optimisticAsserterAddr;

    constructor(C _c) {
        c = _c;
        // record the immutable optimisticAsserter address exposed by C
        optimisticAsserterAddr = address(c.optimisticAsserter());
    }

    // single public entry with inputs controlling which function to call and arguments
    function run(uint8 which, bytes32 identifier, uint256 time, bytes calldata ancillaryData) public payable {
        require(which <= 2, "which must be 0,1,2");

        // We will attempt each of the three onlyOptimisticAsserter-protected functions:
        // which==0 -> requestPrice
        // which==1 -> assertionResolvedCallback
        // which==2 -> assertionDisputedCallback

        // Prepare a sample assertionId for callbacks
        bytes32 assertionId = keccak256(abi.encodePacked(identifier, time, ancillaryData));

        // Call as the current contract (msg.sender = this contract). The rule: if this contract's address equals optimisticAsserter, calls must NOT revert; otherwise they MUST revert due to onlyOptimisticAsserter.
        bool reverted;
        if (which == 0) {
            // requestPrice is non-payable and emits an event. Call and capture revert.
            try c.requestPrice(identifier, time, ancillaryData) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (which == 1) {
            try c.assertionResolvedCallback(assertionId, true) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.assertionDisputedCallback(assertionId) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // The general rule: calls revert iff this contract is not the optimisticAsserter address stored in c.
        // Observe that optimisticAsserterAddr is read at construction time; re-read to be safe.
        address currentOpt = address(c.optimisticAsserter());

        assert(reverted == (address(this) != currentOpt));
    }

    // allow receiving ETH though not used
    receive() external payable {}
}

