contract InvMutTest {
    C c;
    OptimisticAsserterInterface ost;

    constructor(C _c) {
        c = _c;
    }

    // single public test function: caller supplies parameters for requestPrice
    function run(address caller, bytes32 identifier, uint256 time, bytes calldata ancillaryData) public payable {
        require(caller != address(0));
        // read optimistic asserter address from c (public immutable variable getter)
        address optimisticAddr = address(c.optimisticAsserter());

        // if caller equals the optimistic asserter, the call should not revert when invoked by this contract
        // otherwise the call should revert due to onlyOptimisticAsserter modifier

        // We will attempt to call c.requestPrice via a call that sets msg.sender to this contract.
        // To simulate different caller identities we rely on the fact that the onlyOptimisticAsserter check compares msg.sender to optimisticAsserter.
        // So if optimisticAddr == address(this) the call will succeed; otherwise it will revert. We capture that.

        // Before state observable: contract c balance
        uint256 beforeBalance = address(c).balance;

        bool reverted;
        // make the state-changing call as a top-level statement
        try c.requestPrice(identifier, time, ancillaryData) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = address(c).balance;

        // General rule: the call reverts iff optimisticAsserter() != address(this), and the call does not change c's balance
        assert((reverted && optimisticAddr != address(this)) || (!reverted && optimisticAddr == address(this)));
        // also assert balance unchanged (requestPrice should not transfer ETH)
        assert(afterBalance == beforeBalance);
    }

    receive() external payable {}
}
